const R=window.RESEARCH,$=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),F=(x,n=1)=>Number.isFinite(x)?x.toFixed(n):'—',sum=a=>a.reduce((s,v)=>s+v,0),mean=a=>a.length?sum(a)/a.length:0, quant=(a,p)=>{a=[...a].sort((x,y)=>x-y);let i=(a.length-1)*p;return a.length?a[Math.floor(i)]+(a[Math.ceil(i)]-a[Math.floor(i)])*(i%1):0},sd=a=>a.length>1?Math.sqrt(sum(a.map(x=>(x-mean(a))**2))/(a.length-1)):0;
const TOUGHNESS_MAP=new Map(window.TOUGHNESS.rows.map(q=>[q.id,q]));for(const q of R.questions)q.toughness=TOUGHNESS_MAP.get(q.id);
const modules=[['difficulty','◈','Difficulty intelligence','F1'],['monitor','▦','Research monitor','F2'],['subjects','◫','Subject intelligence','F3'],['distributions','▥','Distribution lab','F4'],['inference','⌁','Inference studio','F5'],['questions','▤','Question terminal','F6'],['audit','◇','Tag audit & evidence','F7'],['responses','◉','Response workbench','F8'],['evidence','⊞','Methods & sources','F9']];
let view='difficulty',measure='marks',query='',verdict='all',page=0,dist='stem_words',infer=R.subjects[0],responseData=null,sortKey='marks',sortDir=-1;
$('#nav').innerHTML=modules.map(([id,i,t,f])=>`<a href="#${id}" data-nav="${id}"><span class="nav-icon">${i}</span>${t}<kbd>${f}</kbd></a>`).join('');
for(let id of ['from','to'])$('#'+id).innerHTML=R.years.map(y=>`<option>${y}</option>`).join('');$('#to').value=2026;$('#subject').insertAdjacentHTML('beforeend',R.subjects.map(s=>`<option>${E(s)}</option>`).join(''));
const scopeYears=()=>R.years.filter(y=>y>=+$('#from').value&&y<=+$('#to').value);
const scope=()=>R.questions.filter(q=>q.year>=+$('#from').value&&q.year<=+$('#to').value&&($('#subject').value==='all'||q.subject===$('#subject').value)&&($('#quality').value==='all'||($('#quality').value==='clear'?q.inference_eligible:q.subject_changed)));
const short=s=>({'Engineering Mathematics':'Engineering Math.','Signals and Systems':'Signals & Systems','Electronic Devices':'Electronic Devices','General Aptitude':'General Aptitude'}[s]||s);
const panel=(n,title,sub,body,tools='',foot='')=>`<section class="panel"><div class="panel-head"><div><h2><span>${n}</span>${title}</h2><div class="sub">${sub}</div></div>${tools}</div>${body}${foot?`<div class="panel-foot"><span>${foot}</span><span>EC / RESEARCH</span></div>`:''}</section>`;
const badge=(v,c='')=>`<span class="mini-tag ${c}">${E(v)}</span>`;
const totals=q=>({marks:sum(q.map(x=>x.marks)),count:q.length,years:new Set(q.map(x=>x.year)).size});
function groups(q){let ys=scopeYears();return R.subjects.map(s=>{let a=q.filter(x=>x.subject===s),vals=ys.map(y=>sum(a.filter(x=>x.year===y).map(x=>x.marks)));return {subject:s,questions:a.length,marks:sum(vals),vals,avg:mean(vals),sd:sd(vals),cv:mean(vals)?sd(vals)/mean(vals)*100:0,change:vals.length>1?vals.at(-1)-vals[0]:0}}).filter(x=>x.questions).sort((a,b)=>b.marks-a.marks)}
function metricCards(items){return `<div class="metrics">${items.map(([label,value,note,unit=''])=>`<div class="metric"><div class="metric-top">${label}<span>↗</span></div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-note">${note}</div></div>`).join('')}</div>`}
function spark(vals,color='#7baff5'){let m=Math.max(...vals,1),min=Math.min(...vals),range=m-min||1;return `<svg class="sparkline" viewBox="0 0 100 25" aria-label="Historical marks sparkline"><polyline points="${vals.map((v,i)=>`${3+i*94/Math.max(1,vals.length-1)},${21-(v-min)/range*17}`).join(' ')}" fill="none" stroke="${color}" stroke-width="1.6"/></svg>`}
function lineChart(q=scope()){let ys=scopeYears(),types=['MCQ','NAT','MSQ'],series=types.map(t=>ys.map(y=>{let a=q.filter(x=>x.year===y&&x.type===t);return measure==='marks'?sum(a.map(x=>x.marks)):a.length})),max=Math.max(10,...series.flat()),top=Math.ceil(max/10)*10,x=i=>40+i*610/Math.max(1,ys.length-1),y=v=>218-v/top*180,colors=['#7baff5','#67ccce','#ab98f0'];return `<svg class="chart" viewBox="0 0 690 255" role="img" aria-label="Historical ${measure} by question format">${[0,.25,.5,.75,1].map(v=>`<line class="gridline" x1="38" x2="655" y1="${y(top*v)}" y2="${y(top*v)}"/><text x="9" y="${y(top*v)+3}">${F(top*v,0)}</text>`).join('')}${ys.map((v,i)=>`<text x="${x(i)}" y="243" text-anchor="middle">${v}</text>`).join('')}${series.map((a,k)=>`<polyline points="${a.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="${colors[k]}" stroke-width="2"/>${a.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#171c23" stroke="${colors[k]}" stroke-width="1.5"><title>${ys[i]} / ${types[k]} / ${v} ${measure}</title></circle>`).join('')}`).join('')}</svg>`}
function trendPanel(){return panel('01','Paper composition monitor','Historical format mix · selected scope',`<div class="panel-content"><div class="legend"><span><i></i>MCQ</span><span><i class="cyan"></i>NAT</span><span><i class="purple"></i>MSQ</span><span>UNIT / ${measure.toUpperCase()}</span></div>${lineChart()}</div>`,`<div class="tabs"><button data-measure="marks" class="${measure==='marks'?'active':''}">MARKS</button><button data-measure="questions" class="${measure==='questions'?'active':''}">QUESTIONS</button></div>`,'Historical observations. Lines connect annual records; they are not forecasts.')}
function tableRows(a,full=false){return `<div class="table-scroll"><table class="data-table"><thead><tr><th data-sort="subject">Subject ↕</th><th data-sort="marks">Marks ↕</th><th data-sort="avg">Mean / paper ↕</th>${full?'<th data-sort="sd">SD ↕</th><th data-sort="cv">CV % ↕</th><th>Range</th>':''}<th>History</th><th data-sort="change">Δ first–last ↕</th></tr></thead><tbody>${a.map(s=>`<tr data-select-subject="${E(s.subject)}"><td>${E(short(s.subject))}<small>${s.questions} QUESTIONS</small></td><td class="numeric">${s.marks}</td><td class="numeric">${F(s.avg)}</td>${full?`<td class="numeric">${F(s.sd)}</td><td class="numeric">${F(s.cv)}</td><td class="numeric">${Math.min(...s.vals)}–${Math.max(...s.vals)}</td>`:''}<td>${spark(s.vals)}</td><td class="numeric ${s.change>=0?'up':'down'}">${s.change>0?'+':''}${s.change}</td></tr>`).join('')}</tbody></table></div>`}
function heatmap(){let q=scope(),ys=scopeYears(),gs=groups(q),max=Math.max(1,...gs.flatMap(s=>s.vals));return `<div class="table-scroll panel-content"><table class="heat"><thead><tr><th>MARKS / PAPER</th>${ys.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${gs.map(s=>`<tr><td>${E(short(s.subject))}</td>${s.vals.map((v,i)=>`<td data-scope-year="${ys[i]}" data-heat-subject="${E(s.subject)}" style="background:rgba(90,142,201,${.05+v/max*.65})" title="${E(s.subject)} · ${ys[i]} · ${v} marks">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function formatsPanel(){let q=scope(),a=['MCQ','NAT','MSQ'].map((t,i)=>({t,n:q.filter(x=>x.type===t).length,c:['#7baff5','#67ccce','#ab98f0'][i]})),total=q.length||1;return panel('03','Question structure','Formats and corpus concentration',`<div class="panel-content"><svg class="chart" viewBox="0 0 340 135" role="img" aria-label="Question format counts">${a.map((x,i)=>`<text x="0" y="${30+i*37}" style="fill:#9bb0c9">${x.t}</text><rect x="38" y="${18+i*37}" width="${x.n/total*240}" height="16" rx="2" fill="${x.c}"/><text x="${48+x.n/total*240}" y="${30+i*37}">${x.n} / ${F(x.n/total*100)}%</text>`).join('')}</svg><div class="stat-grid" style="padding:8px 0 0"><div><div class="sub">SUBJECT ENTROPY</div><p class="mono">${F(entropy(groups(q).map(x=>x.marks)),2)} <span class="sub">bits</span></p></div><div><div class="sub">CONCENTRATION</div><p class="mono">${F(hhi(groups(q).map(x=>x.marks)),3)} <span class="sub">HHI</span></p></div></div></div>`,'','Entropy and HHI describe the selected subject mix; not question difficulty.')}
function entropy(a){let t=sum(a);return t?-sum(a.filter(x=>x>0).map(x=>x/t*Math.log2(x/t))):0}function hhi(a){let t=sum(a);return t?sum(a.map(x=>(x/t)**2)):0}
function monitor(){let q=scope(),t=totals(q),ch=q.filter(x=>x.subject_changed).length;return metricCards([['Question records',t.count,'<b>AI REVIEWED</b> · individual rationale attached'],['Historical marks',t.marks,`${t.years} annual papers in scope`],['Canonical subjects',new Set(q.map(x=>x.subject)).size,'<b>SYLLABUS MAPPED</b> · aliases unified'],['Subject corrections',ch,'Before / after evidence available']])+`<div class="grid-main">${trendPanel()}<section class="panel research-note"><div class="overline">◇ &nbsp; EVIDENCE BEFORE INFERENCE</div><h2>Better inputs.<br><span>Sharper conclusions.</span></h2><p>The audit found ${R.summary.corrections_or_refinements} tag corrections or refinements. Every decision links back to a question-level rationale.</p><div class="note-stat"><strong>${R.summary.ambiguous}</strong><span>unresolved taxonomy<br>conventions</span></div><a class="button" href="#audit">Inspect the question audit &nbsp; ↗</a></section></div><div class="grid-two">${panel('02','Subject weightage ledger','Cumulative marks · click a subject to link the workspace',tableRows(groups(q).slice(0,6)),`<a class="link" href="#subjects">FULL LEDGER ↗</a>`,'Means include zero-mark papers within the selected years.')}${formatsPanel()}</div><div class="bottom-band"><span>⌁</span><p><strong>Research-grade separation of evidence.</strong><br>Content estimates are available. Empirical difficulty, discrimination and IRT remain uncalibrated until response data is supplied.</p><a class="link" href="#responses">RESPONSE WORKBENCH ↗</a></div>`}
function subjects(){let a=groups(scope()).sort((a,b)=>(typeof a[sortKey]==='string'?a[sortKey].localeCompare(b[sortKey]):a[sortKey]-b[sortKey])*sortDir);return panel('01','Subject statistics ledger','Click headers to sort · means and SD across selected annual papers',tableRows(a,true),'','CV is sample SD / mean. A small corpus limits trend interpretation.')+`<div style="height:18px"></div>`+panel('02','Year × subject matrix','Each cell is observed marks in one selected paper. Click a year to isolate it.',heatmap(),badge('LINKED SCOPE'),'Topic tags remain content estimates; subject totals reflect reviewed classifications.')}
const distFields={stem_words:{label:'Stem length',unit:'words',get:q=>q.structural.stem_word_count,basis:'Direct text measurement. OCR quality affects length.'},marks:{label:'Question marks',unit:'marks',get:q=>q.marks,basis:'Supplied question metadata; source-key checks are tracked per item.'},operations:{label:'Named cognitive operations',unit:'operations',get:q=>q.structural.cognitive_operations.filter(x=>x!=='not_assessed').length,basis:'Count of reviewer-named operations. This is not a measured reasoning-step count.'},legacy_depth:{label:'Original conceptual depth estimate',unit:'ordinal score',get:q=>q.original_uncalibrated_estimates.conceptual_depth_1_5,basis:'Legacy 1–5 content estimate. No empirical calibration. Ordinal levels have no guaranteed equal spacing.'}};
function distribution(){let f=distFields[dist],a=scope().map(f.get).filter(Number.isFinite).sort((x,y)=>x-y);if(!a.length)return '<div class="empty">No values in this scope.</div>';let lo=a[0],hi=a.at(-1),count=dist==='marks'?2:dist==='legacy_depth'?5:Math.min(14,Math.max(3,Math.ceil(Math.sqrt(a.length)))),width=(hi-lo||1)/count,bins=Array(count).fill(0);a.forEach(v=>bins[Math.min(count-1,Math.floor((v-lo)/width))]++);let max=Math.max(...bins,1),sx=i=>45+i*560/count;
let hist=`<svg class="chart" viewBox="0 0 660 280" role="img" aria-label="Histogram of ${E(f.label)}">${[0,.5,1].map(v=>`<line class="gridline" x1="40" x2="620" y1="${225-v*180}" y2="${225-v*180}"/><text x="8" y="${228-v*180}">${Math.round(v*max)}</text>`).join('')}${bins.map((v,i)=>`<rect x="${sx(i)}" y="${225-v/max*180}" width="${550/count-3}" height="${v/max*180}" rx="2" fill="#6999d0"><title>${F(lo+i*width)}–${F(lo+(i+1)*width)}: ${v} items</title></rect>${i%Math.ceil(count/6)===0?`<text x="${sx(i)}" y="248">${F(lo+i*width,dist==='marks'?1:0)}</text>`:''}`).join('')}<text x="620" y="268" text-anchor="end">${E(f.unit.toUpperCase())}</text></svg>`;
let ecdf=`<svg class="chart" viewBox="0 0 560 280" role="img" aria-label="Empirical cumulative distribution"><line class="gridline" x1="40" x2="520" y1="225" y2="225"/><line class="gridline" x1="40" x2="520" y1="45" y2="45"/><text x="7" y="228">0%</text><text x="0" y="48">100%</text><path d="M40,225 ${a.map((v,i)=>`H${40+(v-lo)/(hi-lo||1)*470} V${225-(i+1)/a.length*180}`).join(' ')}" stroke="#67ccce" stroke-width="1.8" fill="none"/><text x="40" y="250">${F(lo)}</text><text x="510" y="250" text-anchor="end">${F(hi)}</text></svg>`;
return `<div class="toolbar" style="padding:0 0 18px;border:0"><span class="sub">PARAMETER</span><select id="distParam" aria-label="Distribution parameter">${Object.entries(distFields).map(([k,v])=>`<option value="${k}" ${k===dist?'selected':''}>${E(v.label)}</option>`).join('')}</select><span class="result-count">${a.length} non-missing observations</span></div>`+metricCards([['Median',F(quant(a,.5)),`IQR ${F(quant(a,.25))}–${F(quant(a,.75))}`,f.unit],['Sample mean',F(mean(a)),f.basis.slice(0,65)],['Sample SD',F(sd(a)),'Descriptive variation across records'],['Median absolute deviation',F(quant(a.map(x=>Math.abs(x-quant(a,.5))),.5)),'Robust descriptive dispersion']])+`<div class="grid-two">${panel('01','Empirical histogram',E(f.label),`<div class="panel-content">${hist}</div>`,badge('OBSERVED CORPUS'),'Equal-width bins. No fitted distribution is assumed.')}${panel('02','Cumulative distribution','Fraction of corpus at or below each value',`<div class="panel-content">${ecdf}</div>`,'','ECDF is descriptive; questions are clustered within papers.')}</div>`+panel('03','Distribution interpretation','Inspect the basis before using a parameter',`<div class="method-text"><p>${E(f.basis)}</p><p>No normality claim is made. Ordinal content ratings, question marks, and text length answer different questions. They must not be substituted for candidate success probability or calibrated item difficulty.</p><div class="definitions">${[.05,.25,.5,.75,.95].map(p=>`<div><b>${p*100}th percentile</b><p>${F(quant(a,p),2)} ${E(f.unit)}</p></div>`).join('')}</div></div>`)}
function inference(){let s=R.subject_stats.find(x=>x.subject===infer),ys=R.years,vals=s.year_marks,lo=Math.min(...vals,0),hi=Math.max(...vals)+4,y=v=>215-(v-lo)/(hi-lo)*170,x=i=>45+i*590/7,pred=i=>s.mean+s.ols_slope*(i-3.5);return `<div class="quality-banner"><span>ⓘ</span><div><strong>Fixed inference cohort: all eight annual papers, 2019–2026, using all reviewed classifications.</strong><br>Global scope filters do not change this precomputed studio. Permutations assume exchangeable years; bootstrap intervals assume exchangeable annual papers. Neither establishes future GATE weightage.</div></div><div class="toolbar" style="padding:0 0 18px;border:0"><label class="sub">SUBJECT &nbsp;</label><select id="inferSubject" aria-label="Inference subject">${R.subjects.map(x=>`<option ${x===infer?'selected':''}>${E(x)}</option>`).join('')}</select>${badge('n = 8 YEARS','amber')}</div>`+metricCards([['Theil–Sen slope',F(s.theil_sen_slope,3),'Median pairwise annual slope','marks / year'],['OLS slope',F(s.ols_slope,3),'Least-squares linear fit','marks / year'],['Exact permutation p',F(s.permutation_p,4),'Two-sided · all 40,320 year permutations'],['BH-adjusted q',F(s.bh_q,4),`FDR across ${R.subjects.length} subject trend tests`]])+`<div class="grid-two">${panel('01','Historical trend & fitted slope',E(s.subject),`<div class="panel-content"><div class="legend"><span><i></i>OBSERVED MARKS</span><span><i class="cyan"></i>OLS FIT</span></div><svg class="chart" viewBox="0 0 690 265" role="img" aria-label="Subject marks and linear trend">${[0,.5,1].map(v=>`<line class="gridline" x1="40" x2="640" y1="${y(lo+v*(hi-lo))}" y2="${y(lo+v*(hi-lo))}"/><text x="7" y="${y(lo+v*(hi-lo))+3}">${F(lo+v*(hi-lo),0)}</text>`).join('')}<polyline points="${vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" stroke="#7baff5" stroke-width="2" fill="none"/><line x1="${x(0)}" x2="${x(7)}" y1="${y(pred(0))}" y2="${y(pred(7))}" stroke="#67ccce" stroke-dasharray="5 5"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#7baff5"><title>${ys[i]}: ${v} marks</title></circle><text x="${x(i)}" y="244" text-anchor="middle">${ys[i]}</text>`).join('')}</svg></div>`,'','Fit describes these eight years only. No extrapolation shown.')}${panel('02','Robust summary & uncertainty','Annual marks, not independent question-level trials',`<div class="stat-grid">${[['Mean',F(s.mean,2),'marks / paper'],['Median',F(s.median,2),'marks / paper'],['Sample SD',F(s.sd,2),'annual variation'],['IQR',F(s.iqr,2),'middle 50% width'],['MAD',F(s.mad,2),'robust dispersion'],['CV',F(s.cv_pct)+'%','SD / mean'],['Bootstrap 95%',s.bootstrap_mean_ci.map(x=>F(x)).join('–'),'percentile interval for mean'],['Observed in',s.papers_present+'/8','selected years']].map(([a,b,c])=>`<div class="stat-cell"><label>${a}</label><strong>${b}</strong><small>${c}</small></div>`).join('')}</div>`,'','4,000 seeded year-level bootstrap samples; an exploratory interval.')}</div>`+panel('03','Correlations across subject marks','Pearson r across eight annual papers · compositional totals can induce negative correlation',correlation(),'','Descriptive association only. No causal interpretation or unadjusted significance claims.')}
function corr(a,b){let ma=mean(a),mb=mean(b),d=Math.sqrt(sum(a.map(v=>(v-ma)**2))*sum(b.map(v=>(v-mb)**2)));return d?sum(a.map((v,i)=>(v-ma)*(b[i]-mb)))/d:null}
function correlation(){let a=R.subject_stats;return `<div class="table-scroll panel-content"><table class="heat"><thead><tr><th>r / n=8</th>${a.map((s,i)=>`<th title="${E(s.subject)}">${String(i+1).padStart(2,'0')}</th>`).join('')}</tr></thead><tbody>${a.map((s,i)=>`<tr><td>${String(i+1).padStart(2,'0')} ${E(short(s.subject))}</td>${a.map(t=>{let v=corr(s.year_marks,t.year_marks);return `<td style="background:${v>=0?`rgba(95,155,207,${Math.abs(v)*.55})`:`rgba(197,139,91,${Math.abs(v)*.45})`}" title="${E(s.subject)} × ${E(t.subject)}: ${F(v,3)}">${F(v,2)}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function questionList(audit=false){let q=selectedQuestionRows(),a=q.slice(page*15,page*15+15);return `${audit?metricCards([['Semantic reviews',R.summary.semantic_reviews,'All supplied records reviewed'],['Subject changes',R.summary.subject_changes,'Canonical subject reassigned'],['Tag corrections / refinements',R.summary.corrections_or_refinements,'Includes topic-level refinements'],['Ambiguous decisions',R.summary.ambiguous,'Excluded by the clear-tags scope filter']]):''}${audit?'<div class="quality-banner"><span>◇</span><div><strong>Source comparison and clean transcription are separate.</strong> All 520 question identities, source pages and answer keys were reviewed. Two supplied answers were corrected. Remaining transcription defects and four taxonomy ambiguities stay explicit; no human calibration is claimed.</div></div>':''}`+panel('01',audit?'Question-level audit ledger':'Question terminal',audit?'Original tags → reviewed tags · open a row to inspect the reason and source':'Search the full question content, concepts and review rationale',`<div class="toolbar"><input id="search" aria-label="Search question records" placeholder="Search question ID, subject, topic, or reasoning…" value="${E(query)}"><select id="verdict" aria-label="Review filter"><option value="all">All review outcomes</option>${[['consistent','Consistent'],['correction','Corrections / refinements'],['ambiguous','Ambiguous'],['changed','Subject changes'],['risk','Content risk flags']].map(([v,l])=>`<option value="${v}" ${verdict===v?'selected':''}>${l}</option>`).join('')}</select><select id="questionToughnessBand" aria-label="Question toughness band">${["all","Easy","Moderate","Tough"].map(b=>`<option value="${b}" ${b===difficultyQuestionBand?"selected":""}>${b==="all"?"All toughness bands":b}</option>`).join("")}</select><span class="result-count">${q.length} RECORDS</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Question / format</th><th>Reviewed subject & topic</th>${audit?'<th>Original subject</th>':'<th>Content operation</th>'}<th>Toughness / 100</th><th>Review outcome</th><th>Source scope</th></tr></thead><tbody>${a.map(x=>`<tr data-question="${E(x.id)}"><td class="numeric">${x.id.replace('GATE-EC-','')} ↗<small>${x.type} · ${x.marks} MARKS · ${x.scoring_status==='marks_to_all'?'MTA':'STANDARD'}</small></td><td>${E(x.subject)}<small>${E(x.topic)}</small></td><td>${E(audit?x.original_subject:x.structural.cognitive_operations[0])}<small>${audit?(x.subject_changed?'SUBJECT CHANGE':''):'CONTENT ESTIMATE'}</small></td><td>${x.toughness?toughPill(x.toughness.score):"—"}</td><td>${badge(x.review.semantic_verdict,x.review.semantic_verdict==='correction'?'amber':x.review.semantic_verdict==='ambiguous'?'red':'green')}<small>${x.quality.open_issue_count?'OPEN FLAGS: '+x.quality.open_issue_count:E(x.review.confidence)+' CONFIDENCE'}</small></td><td>${x.source.visual_review_completed?'SOURCE REVIEWED':x.source.token_recall!==null?'TEXT ALIGNED':'VISUAL SOURCE'}<small>${x.source.page?'PDF PAGE '+x.source.page:'PAGE REVIEW PENDING'}</small></td></tr>`).join('')}</tbody></table></div>${!q.length?'<div class="empty">No matching records. Broaden the search or reset scope.</div>':''}<div class="pagination"><span>${q.length?page*15+1:0}–${Math.min((page+1)*15,q.length)} / ${q.length} RECORDS</span><div><button id="previous" class="button" ${page===0?'disabled':''}>← Prev</button><button id="next" class="button" ${(page+1)*15>=q.length?'disabled':''}>Next →</button></div></div>`,'','AI review, lexical source alignment and independent calibration are distinct statuses.')}
function inspect(id){let q=R.questions.find(x=>x.id===id);if(!q)return;let ops={};try{ops=JSON.parse(q.options||'{}')||{}}catch{}$('#inspectBody').innerHTML=`<div class="overline">QUESTION INSPECTOR / ${E(q.id)}</div><h2 class="inspect-title">${E(q.microtopic||q.topic)}</h2><div class="legend">${badge(q.subject)}${badge(q.type+' / '+q.marks+' MARKS')}${badge(q.review.semantic_verdict,q.review.semantic_verdict==='consistent'?'green':'amber')}</div><div class="inspect-grid"><div><h3 class="sub">SUPPLIED QUESTION TRANSCRIPTION</h3><p class="inspect-stem">${E(q.stem)}</p>${Object.entries(ops).map(([k,v])=>`<p class="inspect-stem"><b>${E(k)}.</b> ${E(v)}</p>`).join('')}${(q.has_image||q.toughness?.source_preview)?`<img class="inspect-image" src="${q.has_image?"question-images/"+encodeURIComponent(q.id)+".jpg":q.toughness.source_preview}" alt="Question source view ${E(q.id)}">`:'<div class="quality-banner">No extracted image was supplied. Open the official source paper to inspect the complete figure and equations.</div>'}<details class="source-answer"><summary>Reveal reviewed answer key</summary><p>${E(q.reviewed_answer)} · ${E(q.scoring_status)}</p><p class="sub">Original supplied answer: ${E(q.supplied_answer)} · Original supplied answer: ${E(q.supplied_answer)} · Key comparison: ${E(typeof q.source.answer_key_check==='object'?JSON.stringify(q.source.answer_key_check):q.source.answer_key_check||'not separately checked')}</p></details><a class="button" target="_blank" rel="noopener noreferrer" href="${E(q.source.url)}${q.source.page?'#page='+q.source.page:''}">Official paper ${q.source.page?'· page '+q.source.page:''} ↗</a></div><div>${toughInspector(q)}<div class="detail-card"><h3>01 / TAG ADJUDICATION</h3><div class="diff-old">${E(q.original_subject)} / ${E(q.original_topic)}</div><div class="diff-new">→ ${E(q.subject)} / ${E(q.topic)}</div><p>${E(q.review.rationale)}</p><p>Confidence: ${E(q.review.confidence)} · AI content estimate</p></div><div class="detail-card"><h3>02 / STRUCTURAL PARAMETERS</h3><dl><dt>Cognitive operation</dt><dd>${E(q.structural.cognitive_operations.join('; '))}</dd><dt>Bloom estimate</dt><dd>${E(q.structural.bloom_estimate)}</dd><dt>Representations</dt><dd>${E(q.structural.representations.join(', '))}</dd><dt>Figure dependency</dt><dd>${q.structural.figure_dependency?'Present / review needed':'Not identified'}</dd><dt>Negative wording</dt><dd>${q.structural.negative_wording?'Yes':'No'}</dd><dt>Word count</dt><dd>${q.structural.stem_word_count}</dd><dt>Wrong-answer penalty</dt><dd>${F(q.negative_penalty,3)}</dd></dl></div><div class="detail-card"><h3>03 / SOURCE EVIDENCE</h3><p>${E(q.source.review_match)}<br>Automated match: ${E(q.source.text_match)}<br>${q.source.token_recall!==null?'Lexical token recall: '+F(q.source.token_recall*100)+'%':''}</p><p>Text overlap does not certify mathematical coefficients, diagrams, options or the answer key.</p></div>${q.review.verified_content_repairs?`<div class="detail-card"><h3>SOURCE-CONFIRMED REPAIR NOTES</h3><pre class="original-text">${E(JSON.stringify(q.review.verified_content_repairs,null,2))}</pre></div>`:""}<div class="detail-card"><h3>04 / CONTENT & PROVENANCE FLAGS</h3><ul>${q.flags.map(f=>`<li>${E(typeof f==='string'?f:JSON.stringify(f))}</li>`).join('')||'<li>No additional flags in this review.</li>'}</ul></div><div class="detail-card"><h3>05 / EMPIRICAL CALIBRATION</h3><p>Difficulty p, discrimination, IRT α/β/γ and observed time distribution: <b>not estimated</b>. No candidate-response matrix was provided. Original numeric estimates remain quarantined in the audit JSON.</p></div></div></div>`;$('#inspector').showModal()}
function responses(){return panel('01','Candidate response workbench','Local-only CSV import · compute observed item statistics from your own data',`<div class="method-text"><p>Required columns: <code>candidate_id,question_id,correct,response_time_sec</code>. Correct must be 0 or 1. Time is optional and must be non-negative. One response per candidate–question pair. Use pseudonymous candidate IDs.</p><p>For corrected item-total correlation, this tool uses complete candidates who answered every distinct non-MTA item present in the import (at least two items). The table reports pairwise response count separately from complete-candidate count.</p></div><div class="upload"><h3>Bring observations into the terminal.</h3><p>Files are processed in this browser. No upload service is connected.<br>Imported responses affect this workbench only.</p><input id="responseFile" aria-label="Import candidate response CSV" type="file" accept=".csv,text/csv"><p><button class="button" id="template">Download CSV template</button></p><div id="responseError" class="response-error"></div></div><div id="responseResult">${responseData?responseTable():''}</div>`,'','Descriptive item statistics do not constitute IRT calibration or validate population-wide claims.')}
function responseTable(){let d=responseData;return `<div class="quality-banner"><span>ⓘ</span><div>Observed imported sample only. ${d.complete} complete candidates across ${d.items} non-MTA items. Empty correlations indicate fewer than 3 complete candidates, no rest-score variance, or a constant item. Small item samples remain unstable.</div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Question</th><th>n responses</th><th>Success p</th><th>Wilson 95% CI</th><th>Corrected item-total r</th><th>Median time</th></tr></thead><tbody>${d.rows.map(x=>`<tr data-question="${E(x.id)}"><td>${E(x.id)}</td><td class="numeric">${x.n}</td><td class="numeric">${F(x.p,3)}</td><td class="numeric">${F(x.ci[0],3)}–${F(x.ci[1],3)}</td><td class="numeric">${x.r===null?'—':F(x.r,3)}</td><td class="numeric">${x.t===null?'—':F(x.t)+'s'}</td></tr>`).join('')}</tbody></table></div>`}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed quoted field');if(cell||row.length){row.push(cell);rows.push(row)}return rows}
async function importResponses(file){try{if(file.size>10e6)throw Error('File exceeds 10 MB.');let csv=parseCSV((await file.text()).replace(/^\uFEFF/,'')),head=(csv.shift()||[]).map(x=>x.trim()),idx=k=>head.indexOf(k);if(['candidate_id','question_id','correct'].some(k=>idx(k)<0))throw Error('Required columns missing.');let records=[],seen=new Set(),valid=new Set(R.questions.map(q=>q.id));for(let i=0;i<csv.length;i++){let a=csv[i],id=(a[idx('question_id')]||'').trim(),candidate=(a[idx('candidate_id')]||'').trim(),correct=(a[idx('correct')]||'').trim(),time=idx('response_time_sec')<0?'':(a[idx('response_time_sec')]||'').trim(),key=candidate+'\u0000'+id;if(!candidate||!valid.has(id)||!['0','1'].includes(correct))throw Error('Invalid candidate, question ID or correct value on row '+(i+2));if(time!==''&&(!Number.isFinite(+time)||+time<0))throw Error('Invalid response time on row '+(i+2));if(seen.has(key))throw Error('Duplicate candidate–question pair on row '+(i+2));seen.add(key);if(R.questions.find(q=>q.id===id).scoring_status==='marks_to_all')continue;records.push({id,candidate,c:+correct,t:time===''?null:+time})}if(!records.length)throw Error('No scored non-MTA responses found.');let ids=[...new Set(records.map(x=>x.id))],candidates=[...new Set(records.map(x=>x.candidate))],maps=new Map(candidates.map(c=>[c,new Map(records.filter(x=>x.candidate===c).map(x=>[x.id,x.c]))])),complete=candidates.filter(c=>maps.get(c).size===ids.length),rows=ids.map(id=>{let a=records.filter(x=>x.id===id),p=mean(a.map(x=>x.c)),n=a.length,z=1.959964,den=1+z*z/n,center=(p+z*z/(2*n))/den,half=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/den,values=complete.map(c=>maps.get(c).get(id)),rest=complete.map(c=>sum([...maps.get(c)].filter(([k])=>k!==id).map(([k,v])=>v*R.questions.find(q=>q.id===k).marks))),times=a.map(x=>x.t).filter(Number.isFinite);return {id,n,p,ci:[center-half,center+half],r:ids.length>=2&&complete.length>=3&&sd(values)>0&&sd(rest)>0?corr(values,rest):null,t:times.length?quant(times,.5):null}});responseData={rows,complete:complete.length,items:ids.length};$('#responseResult').innerHTML=responseTable();$('#responseError').textContent=''}catch(e){responseData=null;$('#responseResult').innerHTML='';$('#responseError').textContent=e.message}}
function evidence(){return `<div class="quality-banner"><span>◇</span><div><strong>Audit version ${E(R.version)} · 520 / 520 semantic reviews.</strong><br>All decisions are AI content reviews. Online identity matching, full visual verification, answer-key checking and independent human adjudication are separate activities; completion of one never implies completion of another.</div></div>`+panel('01','The evidence model','Four parameter classes, with provenance and missing values preserved',`<div class="method-text"><div class="definitions"><div><b>01 / Source metadata</b><p>Paper, year, section, format, marks, answer/range and negative penalty. Each question links to its official paper and source hash. Marks-to-all records are excluded from response calibration.</p></div><div><b>02 / Reviewed content tags</b><p>Canonical subject, topic, microtopic, secondary subjects, representation, cognitive operation and Bloom estimate. Review rationale, confidence and change history accompany every record.</p></div><div><b>03 / Reproducible derived statistics</b><p>Paper-level weight, sample SD, IQR, MAD, CV, entropy, HHI, exact permutation trend tests, BH correction, Theil–Sen slope, bootstrap intervals, histograms and empirical CDFs.</p></div><div><b>04 / Empirical response parameters</b><p>Difficulty p, corrected item-total correlation, response times, distractor efficacy and fitted IRT require candidate observations. Corpus values are null. Legacy numeric IRT estimates are retained only as uncalibrated provenance.</p></div></div><h3>What was actually checked</h3><p>Every supplied stem, options and classification received a semantic review. All official annual PDFs were downloaded and SHA-256 hashed. ${R.summary.text_aligned_candidates} question transcriptions align lexically with official text-layer segments. The other 195 records belong to image-based papers. Per-question source review and key statuses in the audit ledger describe the completed comparison; lexical overlap cannot certify equations or figures.</p><h3>Statistics and scope</h3><p>Descriptive panels use your active filters. Annual subject means include zero-mark years in that scope. The inference studio uses a fixed cohort of eight full annual papers with all reviewed classifications. The year is the sampling unit. Exact two-sided permutation p-values enumerate all 8! = 40,320 allocations; BH q-values adjust the ten subject trend tests. Bootstrap intervals use 4,000 seeded resamples of eight annual papers with replacement. Both are exploratory because the corpus is small and papers need not be exchangeable.</p><h3>Original data problems are not silently repaired</h3><p>Canonical aliases are merged and proposed semantic corrections drive the new analytics. Original values, content defects, source status and review notes stay in the audit export. Questions with ambiguous tags can be excluded by scope. Other OCR risk flags need source repair before use in automated solving or scored practice. No independent human calibration dataset was supplied.</p><h3>Future predictor integration</h3><p>Stable question IDs, versioned taxonomy and separate response records provide the integration boundary. A rank model will need year-specific marks–rank observations, held-out-year validation and uncertainty intervals. College prediction will need programme, category, round and year-specific official admissions data. Neither predictor is fitted here.</p><p><a class="button" href="question-audit.csv" download>Download all 520 audit rows</a> <a class="button" href="question-audit.json" download>Full evidence JSON</a> <a class="button" href="statistics.json" download>Statistical results</a></p></div>`)+`<div style="height:18px"></div>`+panel('02','Research & design references','Primary sources used for the corpus, statistical method and product direction',`<div class="research-links"><a target="_blank" rel="noopener noreferrer" href="https://gate2026.iitg.ac.in/doc/GATE2026_Syllabus/EC_2026_Syllabus.pdf"><span>01 / TAXONOMY</span><strong>Official GATE EC syllabus ↗</strong><small>Canonical scope; Networks and Signals separated analytically within the combined official section.</small></a><a target="_blank" rel="noopener noreferrer" href="https://gate2026.iitg.ac.in/download.html"><span>02 / CORPUS</span><strong>Official GATE archive ↗</strong><small>Master papers and answer keys. Question order follows master papers.</small></a><a target="_blank" rel="noopener noreferrer" href="https://professional.bloomberg.com/products/bloomberg-terminal/"><span>03 / TERMINAL PATTERNS</span><strong>Bloomberg Terminal ↗</strong><small>Linked workspace, analytical density, monitors and direct function navigation.</small></a><a target="_blank" rel="noopener noreferrer" href="https://www.carbondesignsystem.com/building-blocks/data-visualization/overview"><span>04 / ENTERPRISE CHARTS</span><strong>IBM Carbon ↗</strong><small>Chart choice, consistent hierarchy and enterprise data-visualization vocabulary.</small></a><a target="_blank" rel="noopener noreferrer" href="https://www.publichealth.columbia.edu/research/population-health-methods/item-response-theory"><span>05 / CALIBRATION</span><strong>Columbia: Item Response Theory ↗</strong><small>Model assumptions and why item parameters require observed response evidence.</small></a><a target="_blank" rel="noopener noreferrer" href="https://gate2026.iitg.ac.in/QPs-answer-keys.html"><span>06 / SCORING</span><strong>Official scoring & master keys ↗</strong><small>MCQ penalties, MSQ all-or-nothing scoring, NAT ranges and marks-to-all.</small></a></div>`)}
function render(){view=location.hash.slice(1)||'difficulty';if(!modules.some(x=>x[0]===view))view='difficulty';let title=modules.find(x=>x[0]===view)[2];$('#crumb').textContent=title.toUpperCase();$('#overline').textContent='EC / '+title.toUpperCase();$('#title').textContent=view==='difficulty'?'How hard was each paper?':view==='monitor'?'The intelligence behind the exam.':title;$('#subtitle').textContent=({difficulty:'Easy, moderate and tough. Every year. Every subject. Every topic.',monitor:'Read the evidence. Inspect the uncertainty. Build your advantage.',subjects:'Follow the weight, variation and composition of every subject.',distributions:'Explore the shape of your data before fitting a model.',inference:'Separate a historical pattern from statistical evidence.',questions:'Every question, every tag, every review decision.',audit:'Trace classifications back to their evidence.',responses:'Move from content estimates to observed candidate performance.',evidence:'A research terminal is only as strong as its provenance.'})[view];document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view));$('#content').innerHTML=({difficulty,monitor,subjects:()=>subjects()+topicLedger(),distributions:distribution,inference,questions:()=>questionList(false),audit:()=>questionList(true),responses,evidence})[view]();document.body.classList.remove('menu-open')}
function download(name,text,type='text/csv'){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
$('#export').onclick=()=>{if(view==='difficulty'){exportDifficulty();return}let q=scope(),rows=[['id','year','subject','topic','format','marks','review','source_url'],...q.map(x=>[x.id,x.year,x.subject,x.topic,x.type,x.marks,x.review.semantic_verdict,x.source.url])];download(`gate-ec-${view}-scope.csv`,rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'));toast('Exported '+q.length+' question records in the current scope.')};
function commands(){let value=$('#commandInput').value.toLowerCase(),found=modules.filter(m=>`${m[0]} ${m[2]}`.includes(value)),q=value.length>=3?R.questions.filter(q=>`${q.id} ${q.topic}`.toLowerCase().includes(value)).slice(0,6):[];$('#commandResults').innerHTML=found.map(([id,i,t,f])=>`<button class="command-result" data-command="${id}">${i} &nbsp; ${t}<span>${f}</span></button>`).join('')+q.map(x=>`<button class="command-result" data-question="${E(x.id)}">${E(x.id)}<span>${E(x.subject)}</span></button>`).join('')||'<div class="empty">No matching function or question.</div>'}
function openCommands(){$('#commands').showModal();$('#commandInput').value='';commands();$('#commandInput').focus()}
$('#cmd').onclick=openCommands;$('#commandSide').onclick=openCommands;$('#commandInput').oninput=commands;$('#mobileMenu').onclick=()=>document.body.classList.toggle('menu-open');document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.onclick=e=>{if(e.target===d)d.close()});
for(let id of ['from','to','subject','quality'])$('#'+id).onchange=()=>{if(+$('#from').value>+$('#to').value){if(id==='from')$('#to').value=$('#from').value;else $('#from').value=$('#to').value}page=0;render()};$('#reset').onclick=()=>{$('#from').value=2019;$('#to').value=2026;$('#subject').value='all';$('#quality').value='all';query='';verdict='all';difficultyQuestionBand='all';page=0;render()};
document.addEventListener('click',e=>{let q=e.target.closest('[data-question]'),s=e.target.closest('[data-select-subject]'),m=e.target.closest('[data-measure]'),c=e.target.closest('[data-command]'),sort=e.target.closest('[data-sort]'),y=e.target.closest('[data-scope-year]');if(q){$('#commands').close();inspect(q.dataset.question)}if(s){$('#subject').value=s.dataset.selectSubject;render()}if(m){measure=m.dataset.measure;render()}if(c){$('#commands').close();location.hash=c.dataset.command}if(sort){sortDir=sortKey===sort.dataset.sort?-sortDir:-1;sortKey=sort.dataset.sort;render()}if(y){if(y.dataset.heatSubject)$('#subject').value=y.dataset.heatSubject;$('#from').value=y.dataset.scopeYear;$('#to').value=y.dataset.scopeYear;render()}if(e.target.id==='next'){page++;render()}if(e.target.id==='previous'){page=Math.max(0,page-1);render()}if(e.target.id==='template')download('response-template.csv','candidate_id,question_id,correct,response_time_sec\r\n')});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;query=e.target.value;page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});document.addEventListener('change',e=>{if(e.target.id==='verdict'){verdict=e.target.value;page=0;render()}if(e.target.id==='distParam'){dist=e.target.value;render()}if(e.target.id==='inferSubject'){infer=e.target.value;render()}if(e.target.id==='responseFile'&&e.target.files[0])importResponses(e.target.files[0])});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommands()}if(/^F[1-9]$/.test(e.key)){e.preventDefault();location.hash=modules[+e.key.slice(1)-1][0]}});window.addEventListener('hashchange',()=>{page=0;render();window.scrollTo({top:0,behavior:'instant'})});
$('#ticker').innerHTML=`<span class="ticker-label">EC / CORPUS INTELLIGENCE</span><span>RECORDS <b>520</b><em>8 PAPERS</em></span><span>SEMANTIC REVIEW <b>520 / 520</b></span><span>CANONICAL SUBJECTS <b>10</b></span><span>TAG REFINEMENTS <b>${R.summary.corrections_or_refinements}</b></span><span>CALIBRATED IRT <b>NOT AVAILABLE</b></span>`;

